const agentEmail = payload.agent_email
const managerEmail = payload.manager_email
const serviceAccountJson = env.GOOGLE_DELEGATION_SA_JSON

// No manager assignment is a valid, expected case. Treat it as success.
if (!managerEmail) {
  return {
    status: 'success',
    skipped: true,
    reason: 'no_manager_assignment',
    agent_email: agentEmail ?? null,
    manager_email: null,
    delegation_state: null,
    timestamp: new Date().toISOString(),
  }
}

// Genuinely missing config we can't proceed without. Return instead of throwing.
if (!agentEmail || !serviceAccountJson) {
  return {
    status: 'skipped',
    skipped: true,
    reason: 'missing_required_inputs',
    detail: 'Missing required inputs: payload.agent_email or env.GOOGLE_DELEGATION_SA_JSON',
    agent_email: agentEmail ?? null,
    manager_email: managerEmail,
    delegation_state: null,
    timestamp: new Date().toISOString(),
  }
}

const sa = JSON.parse(serviceAccountJson)

// --- Build and sign a JWT assertion for domain-wide delegation ---
const now = Math.floor(Date.now() / 1000)
const header = { alg: 'RS256', typ: 'JWT', kid: sa.private_key_id }
const claims = {
  iss: sa.client_email,
  sub: agentEmail,
  scope: 'https://www.googleapis.com/auth/gmail.settings.sharing',
  aud: 'https://oauth2.googleapis.com/token',
  iat: now,
  exp: now + 3600,
}

const b64url = (buf) => {
  const bytes = buf instanceof ArrayBuffer ? new Uint8Array(buf) : new TextEncoder().encode(buf)
  let bin = ''
  for (const b of bytes) bin += String.fromCharCode(b)
  return btoa(bin).replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_')
}

const signingInput = `${b64url(JSON.stringify(header))}.${b64url(JSON.stringify(claims))}`

// Import the SA's PEM-encoded PKCS#8 private key
const pem = sa.private_key.replace(/-----(BEGIN|END) PRIVATE KEY-----|\s/g, '')
const keyDer = Uint8Array.from(atob(pem), (c) => c.charCodeAt(0))
const key = await crypto.subtle.importKey(
  'pkcs8',
  keyDer,
  { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' },
  false,
  ['sign'],
)

const sig = await crypto.subtle.sign('RSASSA-PKCS1-v1_5', key, new TextEncoder().encode(signingInput))
const assertion = `${signingInput}.${b64url(sig)}`

// --- Exchange JWT for access token ---
const tokenRes = await fetch('https://oauth2.googleapis.com/token', {
  method: 'POST',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams({
    grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
    assertion,
  }),
})

if (!tokenRes.ok) {
  return {
    status: 'error',
    reason: 'token_exchange_failed',
    detail: `Token exchange failed ${tokenRes.status}: ${await tokenRes.text()}`,
    agent_email: agentEmail,
    manager_email: managerEmail,
    delegation_state: null,
    timestamp: new Date().toISOString(),
  }
}
const { access_token } = await tokenRes.json()

// --- Add the delegate ---
const res = await fetch(
  `https://gmail.googleapis.com/gmail/v1/users/${encodeURIComponent(agentEmail)}/settings/delegates`,
  {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${access_token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ delegateEmail: managerEmail }),
  },
)

if (!res.ok) {
  const errorText = await res.text()

  // 409 "alreadyExists" means the delegate is already in place. That's the
  // desired end state, so treat it as success and keep the workflow going.
  if (res.status === 409 || errorText.includes('alreadyExists')) {
    return {
      status: 'success',
      skipped: true,
      reason: 'delegate_already_exists',
      agent_email: agentEmail,
      manager_email: managerEmail,
      delegation_state: 'accepted',
      timestamp: new Date().toISOString(),
    }
  }

  return {
    status: 'error',
    reason: 'gmail_api_error',
    detail: `Gmail API error ${res.status}: ${errorText}`,
    agent_email: agentEmail,
    manager_email: managerEmail,
    delegation_state: null,
    timestamp: new Date().toISOString(),
  }
}

const result = await res.json()

return {
  status: 'success',
  skipped: false,
  agent_email: agentEmail,
  manager_email: managerEmail,
  delegation_state: result.verificationStatus,
  timestamp: new Date().toISOString(),
}

const agentEmail = payload.agent_email
const managerEmail = payload.manager_email
const serviceAccountJson = env.GOOGLE_DELEGATION_SA_JSON

if (!agentEmail || !managerEmail || !serviceAccountJson) {
  throw new Error('Missing required inputs: payload.agent_email, payload.manager_email, env.GOOGLE_DELEGATION_SA_JSON')
}

const sa = JSON.parse(serviceAccountJson)

const now = Math.floor(Date.now() / 1000)
const header = { alg: 'RS256', typ: 'JWT', kid: sa.private_key_id }
const claims = {
  iss: sa.client_email,
  sub: agentEmail,
  scope: 'https://www.googleapis.com/auth/gmail.settings.sharing',
  aud: 'https://oauth2.googleapis.com/token',
  iat: now,
  exp: now + 3600,
}

const b64url = (buf) => {
  const bytes = buf instanceof ArrayBuffer ? new Uint8Array(buf) : new TextEncoder().encode(buf)
  let bin = ''
  for (const b of bytes) bin += String.fromCharCode(b)
  return btoa(bin).replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_')
}

const signingInput = `${b64url(JSON.stringify(header))}.${b64url(JSON.stringify(claims))}`

const pem = sa.private_key.replace(/-----(BEGIN|END) PRIVATE KEY-----|\s/g, '')
const keyDer = Uint8Array.from(atob(pem), (c) => c.charCodeAt(0))
const key = await crypto.subtle.importKey(
  'pkcs8',
  keyDer,
  { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' },
  false,
  ['sign'],
)

const sig = await crypto.subtle.sign('RSASSA-PKCS1-v1_5', key, new TextEncoder().encode(signingInput))
const assertion = `${signingInput}.${b64url(sig)}`

const tokenRes = await fetch('https://oauth2.googleapis.com/token', {
  method: 'POST',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams({
    grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
    assertion,
  }),
})

if (!tokenRes.ok) {
  throw new Error(`Token exchange failed ${tokenRes.status}: ${await tokenRes.text()}`)
}
const { access_token } = await tokenRes.json()

const res = await fetch(
  `https://gmail.googleapis.com/gmail/v1/users/${encodeURIComponent(agentEmail)}/settings/delegates/${encodeURIComponent(managerEmail)}`,
  {
    method: 'DELETE',
    headers: { Authorization: `Bearer ${access_token}` },
  },
)

// Gmail returns 204 No Content on success; 404 if delegate isn't set.
if (res.status !== 204 && res.status !== 404) {
  throw new Error(`Gmail API error ${res.status}: ${await res.text()}`)
}

return {
  agent_email: agentEmail,
  manager_email: managerEmail,
  removed: res.status === 204,
  was_already_absent: res.status === 404,
  timestamp: new Date().toISOString(),
}
